// <<< BEGIN GENERATED — generado por code/scripts/build-workflow.js, no editar a mano >>>

// Lógica de src/phoneNumbers.js

/**
 * Normalización de números para la WhatsApp Cloud API.
 *
 * Por qué existe: Meta usa dos formatos distintos para el mismo teléfono, y
 * mezclarlos rompe el envío. En los mensajes entrantes el webhook entrega el
 * `wa_id` de un celular argentino CON el 9 de móvil (549XXXXXXXXXX), pero
 * `POST /{phone-number-id}/messages` rechaza exactamente ese número con
 * `(#131030) Recipient phone number not in allowed list` — aunque el número
 * esté agregado y verificado en la lista de destinatarios. Hay que mandarlo
 * SIN el 9 (54XXXXXXXXXX).
 *
 * Verificado contra la API real: enviando a `543511234567` el mensaje sale, y
 * el webhook de estado vuelve con `recipient_id: "5493511234567"` — o sea que
 * Meta normaliza de vuelta a la forma con 9 por su cuenta. El error es
 * engañoso: parece un problema de permisos, pero es de formato.
 */

// El dígito que va entre el código de país y el área para indicar "móvil", y
// que la Cloud API no acepta en el destinatario. Solo se listan los países
// verificados contra la API; el resto de los números pasan sin tocar.
const PREFIJO_MOVIL_POR_PAIS = {
  // Argentina. No hay ambigüedad posible: ningún código de área argentino
  // empieza con 9, así que un número que arranca con 549 es siempre un celular.
  54: '9',
};

function soloDigitos(numero) {
  return String(numero || '').replace(/\D/g, '');
}

/**
 * Pasa un número al formato que espera el campo `to` de la Cloud API: solo
 * dígitos, sin "+" y sin el prefijo de móvil que Meta rechaza.
 *
 * @param {string} numero en cualquier formato (E.164, con espacios, guiones…)
 * @returns {string} solo dígitos, listo para mandar; '' si la entrada es basura
 */
function toWhatsAppRecipient(numero) {
  const digitos = soloDigitos(numero);
  if (!digitos) return '';

  for (const [pais, prefijoMovil] of Object.entries(PREFIJO_MOVIL_POR_PAIS)) {
    const conPrefijo = `${pais}${prefijoMovil}`;
    if (digitos.startsWith(conPrefijo)) {
      return pais + digitos.slice(conPrefijo.length);
    }
  }

  return digitos;
}

// <<< END GENERATED >>>

// El WhatsApp Trigger ya nos entrega el "value" del evento de Meta parseado
// (no el body crudo del webhook): trae messaging_product, metadata, contacts
// y messages. El filtro "messageStatusUpdates: []" del trigger ya descarta
// los eventos que son solo actualizaciones de estado (sent/delivered/read),
// así que acá solo deberían llegar mensajes reales.
const entrada = $input.first().json;

// Lectura tolerante de variables de entorno: si la instancia tiene el acceso
// bloqueado (N8N_BLOCK_ENV_ACCESS_IN_NODE=true), el flujo sigue con el default
// en vez de cortarse.
function leerEnv(clave, porDefecto) {
  try {
    return $env[clave] || porDefecto;
  } catch (error) {
    return porDefecto;
  }
}

const mensajeEntrante = (entrada.messages && entrada.messages[0]) || null;
if (!mensajeEntrante) {
  throw new Error('El evento del webhook de Meta no trae un mensaje ("messages"). ¿Llegó un status update en vez de un mensaje entrante?');
}

const telefonoCrudo = String(mensajeEntrante.from || '').trim();
if (!telefonoCrudo) {
  throw new Error('El mensaje de WhatsApp no trae el campo "from". ¿Está bien configurado el webhook en Meta for Developers?');
}

// Meta manda el número sin "+" (ej. "5493511234567"). Lo normalizamos a E.164
// porque el resto del flujo (logs, mensajes al dueño) espera ese formato.
const telefonoCliente = telefonoCrudo.startsWith('+') ? telefonoCrudo : `+${telefonoCrudo}`;

const contacto = (entrada.contacts && entrada.contacts[0]) || {};
// Solo leemos texto: audio/imagen/etc. quedan con mensaje vacío y terminan en
// derivar_humano, igual que antes (ver "Notes and Limitations" del README).
const mensaje =
  mensajeEntrante.type === 'text'
    ? String((mensajeEntrante.text && mensajeEntrante.text.body) || '').trim()
    : '';

return [
  {
    json: {
      telefonoCliente,
      // Los dos nodos de salida mandan a estos, NO a la versión E.164 de
      // arriba: la Cloud API rechaza el 9 de móvil argentino. Ver el porqué
      // en code/src/phoneNumbers.js.
      telefonoClienteParaEnvio: toWhatsAppRecipient(telefonoCliente),
      telefonoDuenoParaEnvio: toWhatsAppRecipient(leerEnv('OWNER_WHATSAPP_NUMBER', '')),
      nombreCliente: String((contacto.profile && contacto.profile.name) || '').trim() || 'Sin nombre',
      mensaje,
      mensajeVacio: mensaje.length === 0,
      messageSid: mensajeEntrante.id || null,
      agencia: leerEnv('AGENCY_NAME', 'la inmobiliaria'),
      // Proveedor del LLM de clasificación: gemini (default, tiene free tier),
      // anthropic o groq. El modelo y la URL son opcionales — si no se
      // configuran, "Build LLM Request" usa el default de cada proveedor.
      proveedorLlm: leerEnv('LLM_PROVIDER', 'gemini').toLowerCase(),
      modelo: leerEnv('LLM_MODEL', ''),
      apiUrlLlm: leerEnv('LLM_API_URL', '') || null,
      // Solo aplica a Gemini: minimal | low | medium | high, u "off" para no
      // mandar thinkingConfig (necesario si se apunta a un modelo 2.5).
      nivelThinking: leerEnv('LLM_THINKING_LEVEL', ''),
      recibidoEn: new Date().toISOString(),
    },
  },
];

