// Lógica de src/conversationMemory.js

/**
 * Memoria de conversación por número de teléfono.
 *
 * Por qué existe: sin esto cada mensaje se clasifica aislado, y una conversación
 * real de WhatsApp no funciona así. "Busco depto en Nueva Córdoba" seguido de
 * "algo de un dormitorio" son un solo pedido partido en dos: el segundo mensaje
 * no menciona el barrio ni la operación, así que sin contexto el clasificador
 * devuelve entidades casi vacías y la búsqueda arranca de cero.
 *
 * Resuelve dos cosas distintas:
 *
 * 1. **Referencias.** El historial va dentro del prompt para que el modelo
 *    pueda interpretar "ese", "el primero" o "algo más barato".
 * 2. **Acumulación de entidades.** Lo que el cliente ya dijo se fusiona con lo
 *    que dice ahora, así la búsqueda usa el pedido completo y no solo el
 *    último fragmento.
 *
 * Dónde se guarda: en una Data Table de n8n, una fila por teléfono, con el
 * estado serializado como JSON en una columna. Se probó primero con
 * `$getWorkflowStaticData` y **no sirve para esto**: n8n carga la static data
 * al empezar la ejecución y la guarda al terminar, sin bloqueos. Dos mensajes
 * seguidos se solapan (la clasificación tarda varios segundos), las dos
 * ejecuciones parten del mismo snapshot y la última en terminar pisa a la
 * otra — medido en esta demo, con el primer mensaje desapareciendo del
 * historial. La Data Table escribe cuando corre el nodo, no al final, así que
 * el mensaje entrante queda registrado antes de la llamada al LLM.
 *
 * Las funciones son puras: reciben y devuelven objetos, sin tocar n8n. El
 * workflow se encarga de leer y escribir la fila.
 */

// Cuánta inactividad hace que una conversación se considere terminada. Media
// hora es suficiente para un ida y vuelta de WhatsApp sin arrastrar el
// contexto de una consulta de ayer a una nueva de hoy.
const TTL_INACTIVIDAD_MS = 30 * 60 * 1000;

// Cuántos mensajes del cliente se recuerdan. Alcanza para resolver referencias
// sin inflar el prompt (y por lo tanto el costo) de cada clasificación.
const MAX_MENSAJES = 6;

// Las entidades que tiene sentido arrastrar entre mensajes. Se listan explícito
// en vez de fusionar todo lo que venga, para que una clave nueva inventada por
// el modelo no se cuele en la memoria.
const ENTIDADES_ACUMULABLES = [
  'operacion',
  'tipo',
  'barrio',
  'dormitorios',
  'presupuesto',
  'moneda',
  'fecha_visita',
  'hora_visita',
  'referencia_propiedad',
];

const CONVERSACION_VACIA = { mensajes: [], entidades: {}, actualizadoEn: 0 };

function esVacio(valor) {
  return valor === null || valor === undefined || valor === '';
}

/**
 * Fusiona lo que el cliente ya había dicho con lo que dice ahora. Un valor
 * nuevo pisa al anterior (el cliente cambió de idea); un valor ausente deja
 * en pie el anterior (el cliente no lo repitió, pero sigue valiendo).
 */
function combinarEntidades(previas, nuevas) {
  const anteriores = previas || {};
  const actuales = nuevas || {};
  const resultado = {};

  for (const clave of ENTIDADES_ACUMULABLES) {
    const valorNuevo = actuales[clave];
    resultado[clave] = esVacio(valorNuevo) ? anteriores[clave] ?? null : valorNuevo;
  }

  return resultado;
}

/**
 * Interpreta lo que vino de la Data Table. Tolera que la columna llegue como
 * string JSON, como objeto ya parseado, vacía o con basura: ante cualquier
 * duda devuelve una conversación vacía en vez de romper el flujo.
 */
function parseEstado(valor) {
  let crudo = valor;

  if (typeof crudo === 'string') {
    try {
      crudo = JSON.parse(crudo);
    } catch (error) {
      return { ...CONVERSACION_VACIA };
    }
  }

  if (!crudo || typeof crudo !== 'object') return { ...CONVERSACION_VACIA };

  return {
    mensajes: Array.isArray(crudo.mensajes) ? crudo.mensajes.filter((m) => m && m.texto) : [],
    entidades: crudo.entidades && typeof crudo.entidades === 'object' ? crudo.entidades : {},
    actualizadoEn: Number(crudo.actualizadoEn) || 0,
  };
}

function serializarEstado(conversacion) {
  return JSON.stringify(conversacion || CONVERSACION_VACIA);
}

/**
 * Una conversación sigue viva si el último mensaje entró dentro del TTL. La
 * fila vieja puede seguir en la tabla: se ignora y se pisa en la próxima
 * escritura.
 */
function estaVigente(conversacion, ahora, opciones) {
  const ttl = (opciones || {}).ttlMs || TTL_INACTIVIDAD_MS;
  if (!conversacion || !conversacion.actualizadoEn) return false;
  return ahora - conversacion.actualizadoEn <= ttl;
}

/**
 * Lo que usa el workflow al leer la fila: parsea y descarta lo vencido.
 *
 * @returns {{mensajes: Array, entidades: object, actualizadoEn: number}} vacía
 *          si no había fila o si la conversación ya venció
 */
function conversacionActiva(valorDeLaFila, ahora, opciones) {
  const conversacion = parseEstado(valorDeLaFila);
  return estaVigente(conversacion, ahora, opciones) ? conversacion : { ...CONVERSACION_VACIA };
}

/**
 * Suma el mensaje entrante al historial. Se llama antes de clasificar, así la
 * ejecución del mensaje siguiente ya lo encuentra escrito.
 */
function agregarMensaje(conversacion, turno, ahora, opciones) {
  const maxMensajes = (opciones || {}).maxMensajes || MAX_MENSAJES;
  const base = conversacion || CONVERSACION_VACIA;
  const datos = turno || {};

  const mensajes = Array.isArray(base.mensajes) ? base.mensajes.slice() : [];
  const texto = String(datos.mensaje || '').trim();
  if (texto) {
    mensajes.push({ texto, intent: datos.intent || null, en: ahora });
  }

  return {
    mensajes: mensajes.slice(-maxMensajes),
    entidades: base.entidades || {},
    actualizadoEn: ahora,
  };
}

/**
 * Fusiona las entidades que extrajo el clasificador. Se llama después de
 * clasificar, con la conversación ya actualizada por agregarMensaje.
 */
function fusionarEntidades(conversacion, entidades, ahora) {
  const base = conversacion || CONVERSACION_VACIA;

  return {
    mensajes: Array.isArray(base.mensajes) ? base.mensajes : [],
    entidades: combinarEntidades(base.entidades, entidades),
    actualizadoEn: ahora || base.actualizadoEn,
  };
}

/**
 * Arma el bloque de contexto que se le manda al modelo. Devuelve '' cuando no
 * hay nada que contar, para no ensuciar el prompt del primer mensaje.
 *
 * @param {object} conversacion estado ya filtrado por vigencia
 * @param {string} mensajeActual se excluye del historial: ya va aparte en el
 *        prompt, y para cuando se arma el contexto puede estar registrado
 */
function formatearContexto(conversacion, mensajeActual) {
  if (!conversacion) return '';

  const partes = [];
  const todos = Array.isArray(conversacion.mensajes) ? conversacion.mensajes : [];
  const actual = String(mensajeActual || '').trim();

  // El mensaje actual puede estar o no en el historial según cuándo se llame;
  // se saca solo la última aparición para no repetirlo en el prompt.
  const mensajes = todos.slice();
  if (actual) {
    for (let i = mensajes.length - 1; i >= 0; i -= 1) {
      if (mensajes[i].texto === actual) {
        mensajes.splice(i, 1);
        break;
      }
    }
  }

  if (mensajes.length) {
    partes.push('Mensajes anteriores de este cliente (del más viejo al más nuevo):');
    mensajes.forEach((mensaje, indice) => {
      partes.push(`${indice + 1}. "${mensaje.texto}"`);
    });
  }

  const entidades = conversacion.entidades || {};
  const yaDichas = ENTIDADES_ACUMULABLES.filter((clave) => !esVacio(entidades[clave]));

  if (yaDichas.length) {
    if (partes.length) partes.push('');
    partes.push('Datos que este cliente ya dio en mensajes anteriores:');
    yaDichas.forEach((clave) => {
      partes.push(`- ${clave}: ${entidades[clave]}`);
    });
  }

  return partes.join('\n');
}

// <<< END GENERATED >>>

// Arma el prompt que se le manda al modelo. Vive en un nodo aparte para que el
// prompt quede legible acá y no escondido dentro de una expresión del HTTP
// Request.
//
// El item que entra es la fila de la Data Table (o vacío si el cliente nunca
// escribió), así que el mensaje se toma del nodo que lo normalizó.
const item = $('Normalize Inbound Message').first().json;
const fila = $input.first().json || {};

const ahora = Date.now();
// conversacionActiva descarta sola lo que pasó el TTL, así que una fila vieja
// que quedó en la tabla no arrastra contexto de ayer.
const previa = conversacionActiva(fila.estado, ahora);

// El mensaje entrante se suma al historial ya, antes de llamar al LLM: la
// clasificación tarda varios segundos y si el cliente manda otro mensaje
// mientras tanto, esa ejecución tiene que encontrarlo escrito.
const conMensaje = agregarMensaje(previa, { mensaje: item.mensaje }, ahora);
const contexto = formatearContexto(conMensaje, item.mensaje);

const PROMPT_SISTEMA = [
  'Sos el clasificador de mensajes de una inmobiliaria de Córdoba, Argentina.',
  'Tu única tarea es analizar el mensaje de un cliente y devolver un JSON.',
  '',
  'Clasificá el mensaje en EXACTAMENTE uno de estos intents:',
  '',
  '- "consulta_propiedad": busca propiedades para alquilar o comprar, pregunta',
  '  por disponibilidad, precios o características de propiedades.',
  '- "agendar_visita": quiere coordinar, reprogramar o cancelar una visita a una',
  '  propiedad, o propone un día y horario.',
  '- "consulta_general": pregunta por horarios, dirección, requisitos, comisiones,',
  '  formas de pago, tasaciones o políticas de la inmobiliaria.',
  '- "derivar_humano": pide hablar con una persona, hace un reclamo, plantea algo',
  '  legal o contractual, o el mensaje no encaja en ninguna de las anteriores.',
  '',
  'Si el mensaje viene con contexto de mensajes anteriores, usalo: un mensaje',
  'corto que por sí solo parece ambiguo suele ser la continuación del pedido',
  'anterior. Clasificá según el pedido completo, no según el fragmento suelto,',
  'y resolvé las referencias ("ese", "el primero", "algo más barato") contra',
  'ese contexto.',
  '',
  'Extraé también las entidades que aparezcan explícitamente. Si un dato no está',
  'en el mensaje, poné null. No inventes nada.',
  '',
  'Sobre las entidades y el contexto: extraé lo que dice el MENSAJE ACTUAL. Si',
  'el mensaje continúa un pedido anterior, podés incluir además los datos del',
  'contexto que sigan valiendo — se combinan igual de forma automática, así que',
  'repetirlos no molesta y ayuda si algo no llegó a guardarse. Si el cliente',
  'corrige un dato que ya había dado, poné el valor nuevo: eso pisa al anterior.',
  '',
  'Reglas para las entidades:',
  '- "operacion": "alquiler" o "venta".',
  '- "tipo": "departamento", "casa", "ph" o "local".',
  '- "barrio": nombre del barrio tal como lo escribió el cliente.',
  '- "dormitorios": número entero.',
  '- "presupuesto": número sin puntos ni símbolos. "500 mil" es 500000.',
  '- "moneda": "ARS" o "USD". Si habla de dólares o USD, es "USD"; si no, "ARS".',
  '- "fecha_visita": formato YYYY-MM-DD. Resolvé fechas relativas usando la fecha',
  '  de hoy que se indica en el mensaje del usuario.',
  '- "hora_visita": formato HH:MM en 24 horas.',
  '- "referencia_propiedad": código tipo "INM-002" si lo menciona.',
  '',
  'Respondé SOLO con el objeto JSON, sin markdown, sin \`\`\`json y sin texto',
  'alrededor. Formato exacto:',
  '{"intent":"...","confianza":0.0,"entidades":{"operacion":null,"tipo":null,"barrio":null,"dormitorios":null,"presupuesto":null,"moneda":null,"fecha_visita":null,"hora_visita":null,"referencia_propiedad":null}}',
  '',
  '"confianza" es un número entre 0 y 1 que indica qué tan seguro estás del intent.',
].join('\n');

// Le pasamos la fecha de hoy para que pueda resolver "el jueves" o "mañana".
const hoy = new Date();
const fechaHoy = [
  hoy.getFullYear(),
  String(hoy.getMonth() + 1).padStart(2, '0'),
  String(hoy.getDate()).padStart(2, '0'),
].join('-');

const bloques = ['Fecha de hoy: ' + fechaHoy];
if (contexto) {
  bloques.push('', '--- Contexto de la conversación ---', contexto, '--- Fin del contexto ---');
}
bloques.push('', 'Mensaje actual del cliente:', item.mensaje || '(mensaje vacío)');

return [
  {
    json: {
      ...item,
      promptSistema: PROMPT_SISTEMA,
      mensajeUsuario: bloques.join('\n'),
      fechaHoy,
      // Lo que escribe el nodo de Data Table que viene justo después.
      telefono: item.telefonoClienteParaEnvio,
      estadoConMensaje: serializarEstado(conMensaje),
      actualizadoEnIso: new Date(ahora).toISOString(),
      // Para poder ver desde la ejecución qué contexto tenía el modelo.
      contextoConversacion: contexto || null,
      entidadesPrevias: previa.entidades,
    },
  },
];

// <<< BEGIN GENERATED — generado por code/scripts/build-workflow.js, no editar a mano >>>

// Lógica de src/llmProviders.js

/**
 * Config y parsing específicos de cada proveedor de LLM.
 *
 * Existe para que "Classify Intent (LLM)" funcione contra Gemini (tiene free
 * tier), Anthropic o Groq sin tocar el resto del flujo — alcanza con cambiar
 * las variables de entorno LLM_PROVIDER / LLM_MODEL / LLM_API_URL. Ver el
 * README de la demo para el detalle de cómo apuntar a cada uno.
 */

const PROVEEDOR_POR_DEFECTO = 'gemini';

const PROVEEDORES_SOPORTADOS = ['gemini', 'anthropic', 'groq'];

const MODELOS_POR_DEFECTO = {
  // Alias estable de Google, no una versión fechada: apunta siempre al
  // flash vigente, así que no se rompe cada vez que Google retira una
  // versión (p. ej. "gemini-2.5-flash" empezó a devolver 404 "no longer
  // available to new users" mientras se armaba esta demo).
  gemini: 'gemini-flash-latest',
  anthropic: 'claude-sonnet-5',
  groq: 'llama-3.3-70b-versatile',
};

// Cuánto puede "razonar" Gemini antes de responder.
//
// Los modelos Gemini 3+ (a los que apunta hoy gemini-flash-latest) usan
// thinkingLevel; los 2.5 usaban thinkingConfig.thinkingBudget. Mandar
// `thinkingBudget: 0` a un Gemini 3 devuelve 400 INVALID_ARGUMENT — además,
// Flash 3.x directamente no permite apagar el thinking del todo, "minimal" es
// lo más bajo posible (verificado contra la API real: con "minimal" la
// respuesta vuelve con thoughtsTokenCount = 0).
//
// Importa porque los tokens de razonamiento se descuentan de maxOutputTokens:
// sin este límite el modelo gastaba ~700 tokens pensando y devolvía el JSON
// cortado a la mitad.
//
// Valor especial 'off': omite thinkingConfig por completo, que es lo que hay
// que usar si se apunta LLM_MODEL a un modelo viejo de la familia 2.5, que no
// entiende thinkingLevel.
const NIVEL_THINKING_POR_DEFECTO = 'minimal';

function normalizarProveedor(proveedor) {
  return String(proveedor || PROVEEDOR_POR_DEFECTO).toLowerCase().trim();
}

// Schema OpenAPI-subset que espera Gemini en generationConfig.responseSchema.
// A diferencia del JSON Schema estándar, los "type" van en MAYÚSCULA (es el
// enum Type del proto de Gemini, no el responseJsonSchema más nuevo que sí
// acepta minúsculas). Con esto Gemini garantiza la forma del JSON de salida
// en vez de dejarla librada al prompt.
//
// Nota: los 4 intents están repetidos acá (no importados de
// parseClassification.js) a propósito. Ambos módulos se inyectan juntos en
// el mismo Code node ("Parse Classification" en build-workflow.js), así que
// declarar una segunda constante con el mismo nombre en el mismo scope
// rompería la compilación — ver INTENTS_VALIDOS en parseClassification.js.
function campoStringOpcional() {
  return { type: 'STRING', nullable: true };
}

function esquemaClasificacionGemini() {
  return {
    type: 'OBJECT',
    properties: {
      intent: {
        type: 'STRING',
        enum: ['consulta_propiedad', 'agendar_visita', 'consulta_general', 'derivar_humano'],
      },
      confianza: { type: 'NUMBER' },
      entidades: {
        type: 'OBJECT',
        properties: {
          operacion: campoStringOpcional(),
          tipo: campoStringOpcional(),
          barrio: campoStringOpcional(),
          dormitorios: { type: 'INTEGER', nullable: true },
          presupuesto: { type: 'NUMBER', nullable: true },
          moneda: campoStringOpcional(),
          fecha_visita: campoStringOpcional(),
          hora_visita: campoStringOpcional(),
          referencia_propiedad: campoStringOpcional(),
        },
        propertyOrdering: [
          'operacion',
          'tipo',
          'barrio',
          'dormitorios',
          'presupuesto',
          'moneda',
          'fecha_visita',
          'hora_visita',
          'referencia_propiedad',
        ],
      },
    },
    required: ['intent', 'confianza', 'entidades'],
    propertyOrdering: ['intent', 'confianza', 'entidades'],
  };
}

function urlPorDefecto(proveedor, modelo) {
  if (proveedor === 'gemini') {
    return `https://generativelanguage.googleapis.com/v1beta/models/${modelo}:generateContent`;
  }
  if (proveedor === 'anthropic') return 'https://api.anthropic.com/v1/messages';
  if (proveedor === 'groq') return 'https://api.groq.com/openai/v1/chat/completions';
  return null;
}

/**
 * Arma la request para el proveedor pedido. Devuelve url/headers/body como
