].join('\n');

const respuesta = [
  'Dale, esto lo ve mejor una persona del equipo 🙌',
  '',
  'Ya le pasé tu consulta a un asesor de ' + item.agencia + '. Te escriben por acá dentro del horario de atención (lunes a viernes de 9 a 19 hs, sábados de 9 a 13 hs).',
  '',
  'Si mientras tanto querés que busque propiedades o coordinemos una visita, decime nomás.',
].join('\n');

return [{ json: { ...item, mensajeDueno, respuesta } }];

// El nodo de WhatsApp anterior reemplazó el item por la respuesta de su API, así
// que recuperamos el contexto del nodo que lo armó.
const contexto = $('Build Handoff Messages').first().json;
const envio = $input.first().json;

const notificacionAlDueno = envio && envio.error ? 'fallida' : 'enviada';

return [{ json: { ...contexto, notificacionAlDueno } }];

// Cierre del flujo: deja registrado si el mensaje salió o no.
//
// A propósito no se intenta avisar el fallo por WhatsApp: si la API de Meta
// está caída, ese aviso también fallaría. Queda en el log de ejecuciones de
// n8n, que es donde hay que mirarlo (o enchufarle acá un Slack/email de alerta).
const item = $input.first().json;
const contexto = $('Normalize Inbound Message').first().json;

const huboError = Boolean(item && item.error);
const mensajeEnviado = item && Array.isArray(item.messages) ? item.messages[0] : null;

return [
  {
    json: {
      telefonoCliente: contexto.telefonoCliente,
      mensajeOriginal: contexto.mensaje,
      entregado: !huboError,
      whatsappMessageId: (mensajeEnviado && mensajeEnviado.id) || null,
      error: huboError ? item.error.message || String(item.error) : null,
      registradoEn: new Date().toISOString(),
    },
  },
];
